editorial.pythonSolution:
import heapq

class Solution:
    def maxTransactions(self, transactions: List[int]) -> int:
        heap = []
        balance = 0
        count = 0
        for t in transactions:
            balance += t
            count += 1
            if t < 0:
                heapq.heappush(heap, t)
            if balance < 0 and heap:
                worst = heapq.heappop(heap)
                balance -= worst
                count -= 1
        return count

